-- ===== Qori-Niyoziy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Ташмухаммад Кары-Ниязи?', fact_ru = 'Я родился 9 февраля 1897 года в городе Худжанде.' WHERE id = 2052;
UPDATE fact_cards SET topic_ru = 'Моя первая школа', question_ru = 'Какое важное дело совершил Кары-Ниязи в Фергане в 1917 году?', fact_ru = 'В 1917 году я основал в Фергане первую узбекскую школу нового типа. А в 1920 году стал директором Ферганского областного техникума образования и воспитания.' WHERE id = 2053;
UPDATE fact_cards SET topic_ru = 'Университет и ректорство', question_ru = 'Какой университет окончил Кары-Ниязи и когда он был его ректором?', fact_ru = 'Среднеазиатский университет я окончил в 1929 году. В 1931 году я стал профессором, а в 1931–1933 годах был ректором этого университета.' WHERE id = 2054;
UPDATE fact_cards SET topic_ru = 'Мои учебники и книги', question_ru = 'По какой науке Кары-Ниязи написал первые учебники на узбекском языке?', fact_ru = 'Первые учебники на узбекском языке по элементарной и высшей математике написал я. Есть у меня и книга воспоминаний под названием «Школа жизни». Я был также главным редактором журнала «Фан ва турмуш».' WHERE id = 2055;
UPDATE fact_cards SET topic_ru = 'Академия наук', question_ru = 'Когда Кары-Ниязи стал первым президентом Академии наук Узбекистана?', fact_ru = 'В 1940–1943 годах я был председателем президиума Узбекского филиала Академии наук СССР. Когда в 1943 году была создана Академия наук Узбекистана, я был избран её первым президентом и работал в этой должности до 1947 года.' WHERE id = 2056;
UPDATE fact_cards SET topic_ru = 'Мои должности', question_ru = 'В какой должности работал Кары-Ниязи в 1937–1938 годах?', fact_ru = 'В 1937–1938 годах я был народным комиссаром просвещения Узбекистана и председателем Комитета по науке. С 1939 года я заведовал кафедрой математики Ташкентского института инженеров ирригации и механизации.' WHERE id = 2057;
UPDATE fact_cards SET topic_ru = 'Мои звания и награды', question_ru = 'Каких званий и наград удостоился Кары-Ниязи?', fact_ru = 'В 1939 году я стал доктором физико-математических наук и получил звание заслуженного деятеля науки Узбекистана. В 1952 году я был награждён Государственной премией, а в 1967 году удостоился звания Героя Труда.' WHERE id = 2058;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Ташмухаммад Кары-Ниязи?', fact_ru = 'Я скончался 18 марта 1970 года в городе Ташкенте. В том же 1970 году мне была присуждена Государственная премия Узбекистана имени Беруни.' WHERE id = 2059;

-- ===== Toshmuhammad Sarimsoqov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Ташмухаммад Сарымсаков?', fact_ru = 'Я родился 9 октября 1915 года в селении Шахрихан Андижанской области.' WHERE id = 2362;
UPDATE fact_cards SET topic_ru = 'Моя учёба и ректорство', question_ru = 'Где учился Сарымсаков и в каких должностях работал?', fact_ru = 'В 1936 году я окончил Среднеазиатский университет. В этом же университете я работал ассистентом, доцентом, профессором и заведующим кафедрой, а позже стал ректором университета. В 1942 году я стал доктором физико-математических наук и профессором.' WHERE id = 2363;
UPDATE fact_cards SET topic_ru = 'Мои научные работы', question_ru = 'В каких научных областях вёл работу Сарымсаков?', fact_ru = 'Мои научные работы посвящены теории вероятностей, геофизике и вопросам метеорологии. Я основал Ташкентскую научную школу по топологии и функциональному анализу и разработал теорию полуполей и её приложение к теории вероятностей.' WHERE id = 2364;
UPDATE fact_cards SET topic_ru = 'В Академии наук', question_ru = 'В каких должностях работал Сарымсаков в Академии наук?', fact_ru = 'В 1943 году я стал академиком Академии наук Узбекистана. В Академии я работал сперва вице-президентом, затем президентом — в этих должностях я служил с 1943 по 1952 год.' WHERE id = 2365;
UPDATE fact_cards SET topic_ru = 'Министр образования', question_ru = 'На какой государственной должности работал Сарымсаков?', fact_ru = 'В 1959–1971 годах я работал министром высшего и среднего специального образования Узбекистана.' WHERE id = 2366;
UPDATE fact_cards SET topic_ru = 'Мои награды', question_ru = 'Какие награды получил Сарымсаков?', fact_ru = 'Государственной премии Узбекистана имени Беруни я удостаивался дважды — в 1967 и 1992 годах. В 1990 году я получил звание Героя Труда.' WHERE id = 2367;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Сарымсаков?', fact_ru = 'В последние годы жизни, начиная с 1988 года, я работал советником в Президиуме Академии наук. Я скончался 17 декабря 1995 года в городе Ташкенте.' WHERE id = 2368;

-- ===== Yahyo G'ulomov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Яхъя Гулямов?', fact_ru = 'Я родился 5 января 1908 года в городе Ташкенте.' WHERE id = 2378;
UPDATE fact_cards SET topic_ru = 'Мой путь образования', question_ru = 'Где учился Яхъя Гулямов?', fact_ru = 'В 1926 году я окончил Узбекское мужское училище в Ташкенте, а в 1930 году — Педагогическую академию Узбекистана в Самарканде. В 1931–1932 годах я работал преподавателем в Ташкентском педагогическом техникуме.' WHERE id = 2379;
UPDATE fact_cards SET topic_ru = 'Хорезмская экспедиция', question_ru = 'Какую работу вёл Яхъя Гулямов в Хорезмской экспедиции?', fact_ru = 'В 1938–1950 годах я участвовал в Хорезмской археолого-этнографической экспедиции как заместитель начальника. Там я изучал историю орошения, земледелия и становления городской культуры Хорезма.' WHERE id = 2380;
UPDATE fact_cards SET topic_ru = 'Мои раскопки', question_ru = 'Где вёл археологические раскопки Яхъя Гулямов?', fact_ru = 'С 1936 года я руководил несколькими археологическими экспедициями в Ташкенте, Бухаре, Самарканде, Фергане и других местах. Я вёл научные изыскания и в долинах Зеравшана и Ферганы, и в Ташкентском оазисе.' WHERE id = 2381;
UPDATE fact_cards SET topic_ru = 'Мои книги и труды', question_ru = 'Какие труды написал Яхъя Гулямов?', fact_ru = 'В 1941 году я написал труд «Памятники города Хивы». Есть у меня и книга «Возникновение первобытной культуры и орошаемого земледелия в долине Нижнего Зеравшана». Я один из основных авторов многотомных книг «История Узбекистана», «История Самарканда» и «История Бухары».' WHERE id = 2382;
UPDATE fact_cards SET topic_ru = 'Мои научные звания', question_ru = 'Каких научных званий достиг Яхъя Гулямов?', fact_ru = 'В 1950 году я стал доктором исторических наук, в 1955 году — профессором. В 1958 году я получил звание заслуженного деятеля науки Узбекистана, а в 1966 году был избран академиком Академии наук Узбекистана.' WHERE id = 2383;
UPDATE fact_cards SET topic_ru = 'Моя научная школа', question_ru = 'Где работал Яхъя Гулямов и какую научную школу он создал?', fact_ru = 'С 1943 года я заведовал отделом древней и средневековой истории в Институте истории и археологии Академии наук Узбекистана, а в 1956–1959 годах исполнял обязанности директора этого института. Я создал в Узбекистане своеобразную интернациональную научную школу по истории и археологии.' WHERE id = 2384;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Яхъя Гулямов?', fact_ru = 'Я скончался 1 октября 1977 года. Всю свою жизнь я посвятил изучению истории Узбекистана и его древних памятников.' WHERE id = 2385;

-- ===== Yunus Rajabiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Юнус Раджаби?', fact_ru = 'Я родился 17 января 1897 года в городе Ташкенте. С юных лет я был известен как певец со звучным голосом и научился играть на нае и дутаре.' WHERE id = 2386;
UPDATE fact_cards SET topic_ru = 'Моё образование', question_ru = 'Где учился Юнус Раджаби?', fact_ru = 'Сперва я учился в медресе, а в 1919–1923 годах — в Туркестанской народной консерватории. Играть на дутаре я учился у Мирзы Касыма, а народным напевам — у таких наставников, как Хаджи Абдулазиз.' WHERE id = 2387;
UPDATE fact_cards SET topic_ru = 'Мой ансамбль на радио', question_ru = 'Какой коллектив создал Юнус Раджаби на радио?', fact_ru = 'В 1927 году я создал при Радиокомитете Узбекистана ансамбль народных инструментов и много лет был его художественным руководителем. Через радио я донёс народные напевы до всего народа.' WHERE id = 2388;
UPDATE fact_cards SET topic_ru = 'Как я записал «Шашмаком»', question_ru = 'Как Юнус Раджаби сберёг «Шашмаком»?', fact_ru = 'Всю жизнь я собирал напевы и песни «Шашмакома» и записывал их нотами — это моё наследие издано в шести томах. Я подготовил и пятитомное собрание «Узбекская народная музыка», в него вошло около тысячи напевов.' WHERE id = 2389;
UPDATE fact_cards SET topic_ru = 'Ансамбль «Маком»', question_ru = 'Какому знаменитому ансамблю положил начало Юнус Раджаби?', fact_ru = 'В 1959 году я основал ансамбль «Маком» и до конца жизни был его художественным руководителем. Среди моих учеников такие мастера, как Б. Давыдова, К. Исмаилова, К. Джабборов.' WHERE id = 2390;
UPDATE fact_cards SET topic_ru = 'Моё творчество и мои произведения', question_ru = 'Какие произведения создал Юнус Раджаби?', fact_ru = 'Я обработал и возродил немало древних узбекских народных напевов и песен: среди них «Гирья», «Ушшок», «Куча боги», «Чоргох». Я участвовал и в создании музыки к таким музыкальным драмам, как «Фархад и Ширин», «Лейли и Меджнун».' WHERE id = 2391;
UPDATE fact_cards SET topic_ru = 'Мои звания', question_ru = 'Какие звания и награды получил Юнус Раджаби?', fact_ru = 'В 1953 году мне было присвоено звание народного артиста Узбекистана. В 1966 году я был избран академиком Академии наук, а в 1971 году удостоился государственной премии имени Хамзы.' WHERE id = 2392;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Юнус Раджаби?', fact_ru = 'Я скончался 23 апреля 1976 года. Всю свою жизнь я посвятил собиранию и сбережению узбекской народной музыки и передаче её будущим поколениям.' WHERE id = 2393;

-- ===== Lutfixonim Sarimsoqova =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родилась Лютфиханум Сарымсакова?', fact_ru = 'Я родилась в 1896 году в Риштанском районе Ферганской области.' WHERE id = 2211;
UPDATE fact_cards SET topic_ru = 'Мой выход на сцену', question_ru = 'Как она пришла на сцену?', fact_ru = 'В 1924 году я вступила в женский самодеятельный кружок в Коканде и так начала свой сценический путь. В театр меня пригласил великий Хамза Хакимзаде Ниязи. Затем я работала в кокандском, андижанском и маргиланском театрах.' WHERE id = 2212;
UPDATE fact_cards SET topic_ru = 'Мои театральные роли', question_ru = 'Какие роли она играла в театре?', fact_ru = 'Я работала актрисой в Узбекском государственном музыкальном театре — театре Мукими. На сцене я играла такие роли, как Ойсара в «Гульсаре», Кимё в «Нурхон», старуха Ясуман в «Фархаде и Ширин».' WHERE id = 2213;
UPDATE fact_cards SET topic_ru = 'Мои матери в кино', question_ru = 'В каких фильмах она играла роль матери?', fact_ru = 'В кино я создала образы добрых матерей: снималась матерью в «Клятве», Мехринисо в «Об этом говорит вся махалля», сестрицей Фатимой в «Ты не сирота». Весь народ с любовью называл меня «Ая» — матушка.' WHERE id = 2214;
UPDATE fact_cards SET topic_ru = 'Мои песни', question_ru = 'Какие песни она пела?', fact_ru = 'Я была и певицей: я пела такие песни и лапары, как «Ёр-ёр», «Будем здоровы», «Не покачивайся», «Смейся». В 1939–1940 годах я руководила женским ансамблем дутаристок при Государственной филармонии Узбекистана.' WHERE id = 2215;
UPDATE fact_cards SET topic_ru = 'Моё звание народной артистки', question_ru = 'Когда она получила звание народной артистки?', fact_ru = 'В 1937 году мне было присвоено звание народной артистки Узбекистана. Это звание я почитала за любовь моего народа.' WHERE id = 2216;
UPDATE fact_cards SET topic_ru = 'Мои приёмные дети', question_ru = 'Какое милосердие проявила она в годы войны?', fact_ru = 'В годы войны я взяла на воспитание двоих русских детей и растила их с любовью, как собственных.' WHERE id = 2217;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умерла Лютфиханум Сарымсакова?', fact_ru = 'Я прожила почти вековую, славную и непростую жизнь. Год моей смерти в источниках точно не указан.' WHERE id = 2218;

-- ===== Sora Eshonto'rayeva =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родилась Сара Эшонтураева?', fact_ru = 'Я родилась в 1911 году в селении Бешбулак Наманганской области.' WHERE id = 2330;
UPDATE fact_cards SET topic_ru = 'Моя учёба в Москве', question_ru = 'Где училась Сара Эшонтураева?', fact_ru = 'Я училась в узбекской драматической студии в Москве и окончила её в 1927 году. С того же года я начала работать актрисой в Узбекском государственном академическом драматическом театре имени Хамзы.' WHERE id = 2331;
UPDATE fact_cards SET topic_ru = 'Моя работа в театре Хамзы', question_ru = 'В каком театре работала Сара Эшонтураева?', fact_ru = 'С 1927 года я была актрисой Узбекского государственного академического драматического театра имени Хамзы. А в 1943–1945 и 1953–1960 годах я была директором этого театра.' WHERE id = 2332;
UPDATE fact_cards SET topic_ru = 'Моя роль Офелии', question_ru = 'Когда Сара Эшонтураева исполнила роль Офелии?', fact_ru = 'В 1935 году я исполнила роль Офелии в трагедии Шекспира «Гамлет». Именно эта роль принесла мне большую славу.' WHERE id = 2333;
UPDATE fact_cards SET topic_ru = 'Дездемона и «Отелло»', question_ru = 'Какую роль играла Сара Эшонтураева в спектакле «Отелло»?', fact_ru = 'В спектакле Шекспира «Отелло» я играла роль Дездемоны. Премьера этого спектакля прошла в 1941 году в театре Хамзы, а роль Отелло исполнял великий актёр Аброр Хидоятов.' WHERE id = 2334;
UPDATE fact_cards SET topic_ru = 'Мои знаменитые роли', question_ru = 'Какие ещё знаменитые роли исполнила Сара Эшонтураева?', fact_ru = 'Я исполняла роли Джамили в произведении Хамзы «Бай и батрак», Гули в «Алишере Навои», Гулаим в «Муканне». Образы Джамили и Гули занимают в моём творчестве особое место.' WHERE id = 2335;
UPDATE fact_cards SET topic_ru = 'Мои звания и награды', question_ru = 'Какие звания и награды получила Сара Эшонтураева?', fact_ru = 'В 1937 году мне было присвоено звание народной артистки Узбекистана. Государственной премией я награждалась в 1949, 1967 и 1977 годах, а в 1993 году получила орден «Соглом авлод учун».' WHERE id = 2336;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умерла Сара Эшонтураева?', fact_ru = 'Я скончалась в 1998 году в городе Ташкенте. Всю свою жизнь я посвятила сцене узбекского театра.' WHERE id = 2337;

-- ===== O'rol Tansiqboyev =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Урал Тансыкбаев?', fact_ru = 'Я родился 14 января 1904 года в городе Ташкенте. Позже я посвятил всё своё творчество изображению природы родного края.' WHERE id = 2250;
UPDATE fact_cards SET topic_ru = 'Моё образование', question_ru = 'Где Тансыкбаев учился живописи?', fact_ru = 'В 1924 году я окончил Пензенское художественное училище. Затем, в 1924–1928 годах, я учился в студии изобразительного искусства при Государственном музее искусств Узбекистана.' WHERE id = 2251;
UPDATE fact_cards SET topic_ru = 'Моё раннее творчество', question_ru = 'Каковы первые произведения Тансыкбаева?', fact_ru = 'Моё творчество 20–30-х годов отличается разнообразием манеры, жанров и тем: я создал работы «Узбекский портрет», «Борьба», «Караван», «В юрте». Я изучал новое искусство Западной Европы, мексиканских монументалистов, а также среднеазиатскую стенопись и искусство миниатюры.' WHERE id = 2252;
UPDATE fact_cards SET topic_ru = 'Пейзаж — мой главный жанр', question_ru = 'Какой жанр стал ведущим в творчестве Тансыкбаева?', fact_ru = 'С 30-х годов ведущее место в моём творчестве занял пейзаж. В работах «Голубой пейзаж» и «Ночной полив» я ввёл в пейзаж жизненную сценку и черты, выражающие человеческий труд.' WHERE id = 2253;
UPDATE fact_cards SET topic_ru = '«Утро Кайраккумской ГЭС»', question_ru = 'Когда создано «Утро Кайраккумской ГЭС»?', fact_ru = 'В 1957 году я написал индустриальный пейзаж под названием «Утро Кайраккумской ГЭС». В нём я изобразил облик родного края, преображающийся трудом человека.' WHERE id = 2254;
UPDATE fact_cards SET topic_ru = 'Пейзажи родного края', question_ru = 'Какие произведения создал Тансыкбаев после войны?', fact_ru = 'В 1942 году я своими глазами увидел земли под Москвой, где шли бои, и создал цикл «На дорогах войны». После войны в таких работах, как «Колхоз в горах», «Весна в Узбекистане», «Родной край», «Вечер на Иссык-Куле», я воспел красоту родной земли.' WHERE id = 2255;
UPDATE fact_cards SET topic_ru = 'Мои звания и награды', question_ru = 'Какие звания имел Тансыкбаев?', fact_ru = 'В 1944 году я удостоился звания народного художника Узбекистана. А в 1973 году стал лауреатом Государственной премии Узбекистана имени Хамзы.' WHERE id = 2256;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Тансыкбаев?', fact_ru = 'Я творил и в последние свои годы: в 1972 году я создал работы «Осеннее утро», «Вечер» и «Моя песня». Я скончался 18 апреля 1974 года.' WHERE id = 2257;

-- ===== Botir Zokirov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Батыр Закиров?', fact_ru = 'Я родился 26 апреля 1936 года в городе Москве. Мой отец Карим Закиров был знаменитым оперным певцом, мать Шахиста Саидова — актрисой и певицей. Моя сестра Луиза и братья Науфаль, Фаррух, Джамшид и Равшан тоже выросли артистами.' WHERE id = 2130;
UPDATE fact_cards SET topic_ru = 'Песня «Арабское танго»', question_ru = 'Когда и где Батыр Закиров впервые исполнил «Арабское танго»?', fact_ru = 'В 1957 году на международном фестивале молодёжи и студентов в Москве я впервые исполнил «Арабское танго». Эту египетскую песню я спел на арабском языке, и она прославилась в народе вместе с моим именем.' WHERE id = 2131;
UPDATE fact_cards SET topic_ru = 'Где я учился', question_ru = 'Где учился Батыр Закиров?', fact_ru = 'В 1952–1957 годах я учился на вокальном факультете Ташкентской государственной консерватории. А в 1958–1962 годах — на режиссёрском факультете Ташкентского государственного института театрального и художественного искусства.' WHERE id = 2132;
UPDATE fact_cards SET topic_ru = 'Мой путь на эстраде', question_ru = 'Какое место занимал Батыр Закиров в узбекской эстраде?', fact_ru = 'Я основатель узбекского современного профессионального эстрадного пения. Я был солистом ансамбля «Ёшлик» (1957) и Узбекского государственного эстрадного оркестра (1958–1970). В 1972–1978 годах я был организатором, солистом и художественным руководителем Ташкентского мюзик-холла.' WHERE id = 2133;
UPDATE fact_cards SET topic_ru = 'Песни народов мира', question_ru = 'Песни каких народов пел Батыр Закиров?', fact_ru = 'Я пел индийские, иранские, египетские, сирийские, ливанские, мексиканские и итальянские песни — каждую на её языке; среди них «Маро бебус», «Мечта сердца», «Плачу о своём прошлом». Я гастролировал во Франции, Австрии, Германии, на Кубе, а также в странах Африки.' WHERE id = 2134;
UPDATE fact_cards SET topic_ru = 'Живопись и писательство', question_ru = 'Каким ещё творчеством, кроме пения, занимался Батыр Закиров?', fact_ru = 'Как художник я создал такие работы, как «Автопортрет», «Зной», «Купола», «Улица детства», «Чор-Минор». Я писал рассказы, очерки и стихи, а также либретто оперы «Барс согдийской земли». Я перевёл на узбекский язык «Маленького принца» Антуана де Сент-Экзюпери и «Тень» Евгения Шварца.' WHERE id = 2135;
UPDATE fact_cards SET topic_ru = 'Мои роли в кино', question_ru = 'В каких фильмах снялся Батыр Закиров?', fact_ru = 'Как киноактёр я создал образы молодого инженера в фильме «Когда расцветают цветы», индийского писателя Рабиндраната Тагора в «Огненных дорогах» и Абдуллы в «Юности гения».' WHERE id = 2136;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Батыр Закиров?', fact_ru = 'Даже в те дни, когда я тяжело болел и в московской больнице готовился ко второй операции, я не оставлял творчества — тогда и была создана песня «Эй сарбон». Я скончался 23 января 1985 года в городе Ташкенте.' WHERE id = 2137;
